const a = $input.all();
if (a.length >= 10000) throw Error("IMAP limit reached; narrow or increase the limit before retry");
return a.filter((x) => x.json.uid);

const { simpleParser } = require("mailparser");
const items = $input.all(),
  emails = [];
for (let i = 0; i < items.length; i++) {
  const b = await $helpers.getBinaryDataBuffer(i, "data");
  const m = await simpleParser(b);
  emails.push({
    uid: items[i].json.uid,
    messageId: m.messageId,
    subject: m.subject,
    from: m.from?.text,
    date: m.date?.toISOString(),
    references: m.references,
    inReplyTo: m.inReplyTo,
    text: m.text,
    htmlText:
      typeof m.html === "string"
        ? m.html.replace(/<script[\s\S]*?<\/script>|<style[\s\S]*?<\/style>|<[^>]+>/gi, " ")
        : "",
  });
}
function group({ payload }) {
  const rows = payload.emails;
  if (!Array.isArray(rows)) throw Error("Expected complete email list");
  const cutoff = Date.now() - 86400000,
    clean = (x) =>
      String(x ?? "")
        .replace(/\s+/g, " ")
        .trim(),
    threads = new Map(),
    seen = new Set();
  for (const r of rows) {
    if (!r || typeof r !== "object") throw Error("Invalid email");
    const date = r.date ? Date.parse(r.date) : NaN;
    if (Number.isFinite(date) && date < cutoff) continue;
    const subject = clean(r.subject) || "(no subject)",
      normal = subject.replace(/^((re|fw|fwd|aw|sv)\s*:\s*)+/i, "").trim() || "(no subject)",
      refs = Array.isArray(r.references) ? r.references.join(" ") : clean(r.references),
      reply = clean(r.inReplyTo),
      key = refs
        ? "ref:" + refs.split(/\s+/)[0].replace(/[<>]/g, "")
        : reply
          ? "reply:" + reply.replace(/[<>]/g, "")
          : "subj:" + normal.toLowerCase(),
      unique = (r.messageId || r.uid) + ":" + key;
    if (seen.has(unique)) continue;
    seen.add(unique);
    const m = {
      subject,
      normal,
      from: clean(r.from),
      date: Number.isFinite(date) ? new Date(date).toISOString() : "",
      body: String(r.text || r.htmlText || "")
        .replace(/https?:\/\/\S+|www\.\S+/gi, " ")
        .split(/\r?\n/)
        .map((x) => clean(x))
        .filter(
          (x) =>
            x &&
            !(
              /unsubscribe|manage preferences|view in browser|privacy policy|terms of service/i.test(
                x,
              ) && x.length < 160
            ),
        )
        .join("\n")
        .slice(0, 2000),
    };
    if (!threads.has(key)) threads.set(key, []);
    threads.get(key).push(m);
  }
  const list = [];
  for (const [key, items] of threads) {
    items.sort((a, b) => a.date.localeCompare(b.date));
    const last = items.at(-1),
      chosen = items.slice(-6);
    let text = "";
    for (const [i, m] of chosen.entries()) {
      const part = `Message ${i + 1}\nDate: ${m.date || "-"}\nFrom: ${m.from || "-"}\nSubject: ${m.subject}\nBody: ${m.body || "(no readable body)"}`;
      if (text && text.length + part.length + 2 > 6000) break;
      text += (text ? "\n\n" : "") + part;
    }
    list.push({
      threadKey: key,
      normalizedSubject: last.normal,
      latestSubject: last.subject,
      latestFrom: last.from,
      messageCount: items.length,
      lastDateIsoUtc: last.date,
      conversationText: text,
    });
  }
  return { payload: { threads: list, emails: [], count: seen.size, threadCount: list.length } };
}

return [{ json: group({ payload: { emails } }).payload }];

